const api = async (path, options = {}) => {
  const isAiMediaRequest = /^\/catalog\/(?:generate|transcribe|speak|remove-background)(?:\/|$)/.test(path);
  if (offlineModeActive && !isAiMediaRequest) return offlineApi(path, options);
  const isFormData = typeof FormData !== 'undefined' && options.body instanceof FormData;
  let response;
  try { response = await fetch(`${API_ORIGIN}/api${path}`, { ...options, signal: options.signal || AbortSignal.timeout(90000), headers: { ...(isFormData ? {} : { 'Content-Type': 'application/json' }), ...(options.headers || {}) } }); }
  catch {
    if (isAiMediaRequest) throw new Error(path.includes('/remove-background')
      ? 'Martisan photo enhancement needs the local API. Start or restart Martisan with START_MARTISAN_OFFLINE.bat, keep its server window open, and retry. Your original photo is still safe.'
      : 'The Martisan AI service is not reachable. Start or restart the local API and check internet access, then retry.');
    offlineModeActive = true; window.dispatchEvent(new Event('martisan-offline')); return offlineApi(path, options);
  }
  if (response.status === 204) return null;
  const result = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(result.detail || result.error?.message || result.message || 'The server could not complete this request.');
  return result;
};

