      if(role==='seller'){const [d,b]=await Promise.all([api(`/dashboard?artisan=${encodeURIComponent(profile.name)}`),api(`/buyers?artisan=${encodeURIComponent(profile.name)}`)]);setDashboard(d);setBuyers(b)}
