    if(transcript.trim())form.append('transcript',transcript.trim());
    if(imageFile)form.append('image',imageFile,imageFile.name||'artisan-product-image');
    else if(imageData){const blob=await imageDataBlob(imageData);const extension=blob.type==='image/webp'?'webp':blob.type==='image/jpeg'?'jpg':'png';form.append('image',blob,`artisan-product-image.${extension}`)}
    setCatalogBusy(true);setCatalogError('');
