    if(offlineModeActive)return localEnhancer(imageFile);
    const remoteEnhancer=async file=>{const form=new FormData();form.append('image',file,file.name||'artisan-product');return api('/catalog/remove-background',{method:'POST',body:form,signal:AbortSignal.timeout(20000)});};
    try{return await enhancePhotoWithFallback(imageFile,remoteEnhancer,localEnhancer)}
