  const ensureCatalogDescriptions=()=>{const fallback=offlineCatalogFromFacts(voiceTranscript,draft,appLanguage);return {...draft,product_name_hi:draft.product_name_hi||fallback.productNameHindi,description_en:draft.description_en?.trim()&&!descriptionHasContact(draft.description_en)?draft.description_en:fallback.descriptionEnglish,description_hi:draft.description_hi?.trim()&&!descriptionHasContact(draft.description_hi)?draft.description_hi:fallback.descriptionHindi}};const catalogReviewDraft=ensureCatalogDescriptions();const publish=async()=>{const catalogCopy=ensureCatalogDescriptions();const description=draft.description||'';const stock=Number(draft.stock||0);const materialCost=Number(draft.material_cost||0),labourCost=Number(draft.labour_cost||0);const p={name:draft.name,product_name_hi:catalogCopy.product_name_hi||'',price:Number(draft.price),stock,category:draft.category,image:photo?'uploaded':draft.image,photo:photo||null,source_photo:sourcePhoto||null,artisan:profileName,tags:draft.keywords.length?draft.keywords:['Handmade','Traditional'],description,description_en:catalogCopy.description_en,description_hi:catalogCopy.description_hi,features_en:draft.features_en||[],features_hi:draft.features_hi||[],material:draft.material||'',color:draft.color||'',size:draft.size||'',making_method:draft.making_method||'',production_time:draft.production_time||'',style:draft.style||'',suggested_uses:draft.suggested_uses||'',craft_information:draft.craft_information||'',material_cost:materialCost,labour_cost:labourCost,production_cost:materialCost+labourCost||Number(draft.production_cost)||0,status:draft.status==='Draft'?'Draft':stock===0?'Out of stock':'Active'};try{const saved=await api(editingId?`/products/${encodeURIComponent(editingId)}`:'/products',{method:editingId?'PUT':'POST',body:JSON.stringify(p)});setProducts(old=>editingId?old.map(x=>x.id===editingId?saved:x):[saved,...old]);setDashboard(await api(`/dashboard?artisan=${encodeURIComponent(profileName)}`));resetDraft();go(destinationAfterPublish());say(editingId?ui.productUpdated:ui.productPublished)}catch(error){say(error.message)}};  const placeOrder=async()=>{if(!cartCount){say(ui.emptyCart);return}try{const order=await api('/orders',{method:'POST',body:JSON.stringify({user_id:'demo-buyer'})});setOrders(old=>[order,...old]);setCart([]);go('orders');say(ui.orderSuccess)}catch(error){say(error.message)}};
